def solve(n, threshold, head_numerator, head_denominator):
    a = head_numerator
    b = head_denominator - a
    coefficient = 1
    weight = b ** n
    size_mass = 0
    power_mass = 0
    for k in range(n + 1):
        if k >= threshold:
            size_mass += coefficient
            power_mass += coefficient * weight
        if k < n:
            coefficient = coefficient * (n - k) // (k + 1)
